one=np.ones_like(t)
def nm(cols):
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt), np.round(c,4)
